  static List<VocabularyWord> search(String query) {
    if (query.isEmpty) return [];
    final q = query.toLowerCase();
    return getAllWords().where((w) {
      return w.japanese.contains(query) ||
          w.hiragana.contains(query) ||
          w.romaji.toLowerCase().contains(q) ||
          w.vietnamese.toLowerCase().contains(q) ||
          w.english.toLowerCase().contains(q);
    }).toList();
  }
